#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void reduce_sum_kernel(const scalar_t* __restrict__ input,
                                  scalar_t* __restrict__ output,
                                  int64_t outer,
                                  int64_t reduce,
                                  int64_t inner) {
    int64_t idx_outer = blockIdx.x;
    int64_t idx_inner = blockIdx.y * blockDim.x + threadIdx.x;
    if (idx_inner >= inner) return;

    float sum = 0.0f;
    for (int64_t r = 0; r < reduce; ++r) {
        int64_t index = idx_outer * (reduce * inner) + r * inner + idx_inner;
        sum += __half2float(input[index]);
    }
    output[idx_outer * inner + idx_inner] = __float2half(sum);
}

torch::Tensor reduce_sum_fp16(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::ScalarType::Half,
                "input must be of type torch.float16 (Half)");

    auto sizes = input.sizes();
    int64_t ndim = sizes.size();
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    int64_t outer = 1;
    for (int64_t i = 0; i < dim; ++i) outer *= sizes[i];
    int64_t reduce = sizes[dim];
    int64_t inner = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner *= sizes[i];

    std::vector<int64_t> out_sizes(sizes.vec());
    out_sizes[dim] = 1;
    auto output = torch::empty(out_sizes, input.options());

    const int threads = 256;
    dim3 block(threads);
    dim3 grid(outer, (inner + threads - 1) / threads);

    reduce_sum_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<half*>(output.data_ptr<at::Half>()),
        outer, reduce, inner);

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("reduce_sum_fp16", &reduce_sum_fp16, "Half‑precision sum reduction over a dimension (CUDA)");
}
'''

# Build the inline extension
_reduce_sum_mod = load_inline(
    name="reduce_sum_fp16_ext",
    cpp_sources=src,
    functions=["reduce_sum_fp16"],
    verbose=False,
